SELECT * FROM t_ai_resource_model


        AND status = #{inputDto.status}


        AND provider_id = #{inputDto.providerId}


        AND code like CONCAT('%', #{inputDto.code}, '%')


        AND name like CONCAT('%', #{inputDto.name}, '%')


        AND description like CONCAT('%', #{inputDto.description}, '%')


        AND create_time > #{inputDto.createStartTime}


        AND create_time  <   #{inputDto.createEndTime}


        AND update_time > #{inputDto.updateStartTime}


        AND update_time  <   #{inputDto.updateEndTime}


ORDER BY create_time DESC
